initJs:
function(container, apiUrl, tables) {
  let testHistoryData = [];
  let currentTestResult = null;

  // テスト履歴の再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}">
        <td>${r.executionDate || ''}</td>
        <td>${r.modelName || ''}</td>
        <td>${r.testPeriod || ''}</td>
        <td>${r.storeCount || ''}</td>
        <td>${r.mape || ''}%</td>
        <td>${r.rmse || ''}</td>
        <td>${r.runtime || ''}秒</td>
        <td><span class="status-${r.status || 'unknown'}">${r.statusText || ''}</span></td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id || ''}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id || ''}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      const rows = await window.aivicApi.list(0);
      if (rows) {
        testHistoryData = rows;
        renderTestHistory(testHistoryData);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 予測精度指標の更新
  function updateMetrics(metrics) {
    container.querySelector("#metric-mape").textContent = metrics.mape || '-';
    container.querySelector("#metric-rmse").textContent = metrics.rmse || '-';
    container.querySelector("#metric-r2").textContent = metrics.r2 || '-';
    container.querySelector("#metric-runtime").textContent = metrics.runtime || '-';
  }

  // グラフの描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!actualData || !predictedData || actualData.length === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('テスト実行後にグラフが表示されます', canvas.width / 2, canvas.height / 2);
      return;
    }

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの最大値・最小値を計算
    const allValues = [...actualData, ...predictedData];
    const maxValue = Math.max(...allValues);
    const minValue = Math.min(...allValues);
    const valueRange = maxValue - minValue;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // 実績値の線（青）
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = padding + chartHeight - ((actualData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値の線（赤）
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (predictedData.length - 1)) * chartWidth;
      const y = padding + chartHeight - ((predictedData[i] - minValue) / valueRange) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(padding + 20, 20, 15, 3);
    ctx.fillStyle = '#d0e4ff';
    ctx.font = '14px Arial';
    ctx.fillText('実績値', padding + 45, 30);

    ctx.fillStyle = '#ef4444';
    ctx.fillRect(padding + 120, 20, 15, 3);
    ctx.fillStyle = '#d0e4ff';
    ctx.fillText('予測値', padding + 145, 30);
  }

  // モデルパラメータの表示
  function displayModelParams(params) {
    const content = container.querySelector("#model-params-content");
    if (!params) {
      content.innerHTML = '<p class="muted">テスト実行後にパラメータ詳細が表示されます</p>';
      return;
    }

    content.innerHTML = `
      <div class="params-grid">
        <div><strong>学習率:</strong> ${params.learningRate || 'N/A'}</div>
        <div><strong>エポック数:</strong> ${params.epochs || 'N/A'}</div>
        <div><strong>バッチサイズ:</strong> ${params.batchSize || 'N/A'}</div>
        <div><strong>隠れ層数:</strong> ${params.hiddenLayers || 'N/A'}</div>
        <div><strong>正則化係数:</strong> ${params.regularization || 'N/A'}</div>
        <div><strong>最適化手法:</strong> ${params.optimizer || 'N/A'}</div>
      </div>
    `;
  }

  // バリデーション関数
  function validateTestConfig() {
    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');

    if (!model) {
      alert('予測モデルが選択されていません');
      return false;
    }

    if (!startDate || !endDate) {
      alert('テスト期間を設定してください');
      return false;
    }

    if (new Date(endDate) < new Date(startDate)) {
      alert('終了日は開始日より後の日付を設定してください');
      return false;
    }

    if (selectedStores.length === 0) {
      alert('対象店舗を選択してください');
      return false;
    }

    if (!category) {
      alert('商品カテゴリが未選択です');
      return false;
    }

    if (!dataset) {
      alert('テストデータセットが選択されていません');
      return false;
    }

    return true;
  }

  // テスト実行
  async function runModelTest() {
    if (!validateTestConfig()) return;

    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;
    const dataset = container.querySelector('input[name="dataset"]:checked').value;
    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value).filter(v => v);

    // テスト実行中の表示
    updateMetrics({ mape: '実行中...', rmse: '実行中...', r2: '実行中...', runtime: '実行中...' });

    try {
      // モックデータでテスト結果をシミュレート
      await new Promise(resolve => setTimeout(resolve, 2000)); // 2秒待機

      const mockResult = {
        mape: (Math.random() * 20 + 5).toFixed(2),
        rmse: (Math.random() * 50 + 10).toFixed(1),
        r2: (Math.random() * 0.3 + 0.7).toFixed(3),
        runtime: (Math.random() * 120 + 30).toFixed(1)
      };

      // 結果の表示
      updateMetrics(mockResult);

      // モックグラフデータ
      const actualData = Array.from({length: 30}, () => Math.random() * 100 + 50);
      const predictedData = actualData.map(val => val + (Math.random() - 0.5) * 20);
      drawComparisonChart(actualData, predictedData);

      // モデルパラメータの表示
      displayModelParams({
        learningRate: '0.001',
        epochs: '100',
        batchSize: '32',
        hiddenLayers: '3',
        regularization: '0.01',
        optimizer: 'Adam'
      });

      // テスト履歴に追加
      const newHistory = {
        id: Date.now().toString(),
        executionDate: new Date().toLocaleString(),
        modelName: model,
        testPeriod: `${startDate} ～ ${endDate}`,
        storeCount: selectedStores.length,
        mape: mockResult.mape,
        rmse: mockResult.rmse,
        runtime: mockResult.runtime,
        status: 'success',
        statusText: '完了'
      };

      const saved = await window.aivicApi.save(0, newHistory);
      if (saved) {
        testHistoryData.unshift(saved);
        renderTestHistory(testHistoryData);
      }

      currentTestResult = mockResult;

    } catch (error) {
      console.error('テスト実行エラー:', error);
      updateMetrics({ mape: 'エラー', rmse: 'エラー', r2: 'エラー', runtime: 'エラー' });
    }
  }

  // CSVエクスポート
  function exportTestResult() {
    if (!currentTestResult) {
      alert('エクスポートするテスト結果がありません');
      return;
    }

    const csvData = [
      ['項目', '値'],
      ['MAPE', currentTestResult.mape + '%'],
      ['RMSE', currentTestResult.rmse],
      ['R²', currentTestResult.r2],
      ['実行時間', currentTestResult.runtime + '秒'],
      ['実行日時', new Date().toLocaleString()]
    ];

    const csvContent = '\uFEFF' + csvData.map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `model_test_result_${new Date().toISOString().slice(0,10)}.csv`;
    link.click();
  }

  // 全店舗選択の処理
  container.querySelector("#store-all").addEventListener("change", function() {
    const isChecked = this.checked;
    container.querySelectorAll('.store-checkbox:not(#store-all)').forEach(cb => {
      cb.checked = isChecked;
    });
  });

  // テスト実行ボタン
  container.querySelector("#btn-run-test").addEventListener("click", runModelTest);

  // エクスポートボタン
  container.querySelector("#btn-export-result").addEventListener("click", exportTestResult);

  // 履歴の操作（削除・詳細表示）
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;

      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);

      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) {
        testHistoryData = updatedRows;
        renderTestHistory(testHistoryData);
      }
      return;
    }

    const viewBtn = e.target.closest(".view-detail-btn");
    if (viewBtn) {
      const id = viewBtn.dataset.id;
      const history = testHistoryData.find(h => h.id === id);
      if (history) {
        alert(`テスト詳細:\n実行日時: ${history.executionDate}\nモデル: ${history.modelName}\n期間: ${history.testPeriod}\nMAPE: ${history.mape}%`);
      }
    }
  });

  // 初期化
  loadInitialData();
  drawComparisonChart([], []); // 空のグラフを初期表示
  displayModelParams(null); // 初期パラメータ表示
}
